#!/bin/bash

APACHE_LICENSE=""

rm -rf node_modules
npm install

# Copy mermaid dist files.
rm -rf docs/mermaid
cp -R node_modules/mermaid/dist docs/mermaid

# Copy mermaid-elk dist files.
rm -rf docs/mermaid-elk
cp -R node_modules/@mermaid-js/layout-elk/dist docs/mermaid-elk

# Copy monaco-editor dist files.
rm -rf docs/monaco-editor
cp -R node_modules/monaco-editor docs/monaco-editor
rm -rf docs/monaco-editor/dev
rm -rf docs/monaco-editor/esm
rm -rf docs/monaco-editor/min-maps

# Download Material Symbols stylesheet. The user-agent forces the woff2 font to
# be linked.
rm -rf docs/material-symbols
curl -A "Firefox/999.0" -s "https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded:opsz@20" -o input.css

# Identify font URL, download it and convert it to base64 in a file.
FONT_URL=$(grep -oP 'url\(\K[^)]+' input.css)
curl -s "$FONT_URL" -o font.woff2
BASE64_FONT=$(base64 -w 0 font.woff2)
echo -n "data:font/woff2;base64," > font.woff2.b64
base64 -w 0 font.woff2 >> font.woff2.b64

# Replace font URL with a place holder and then replace the placeholder with
# the base64 file content.
sed "s|$FONT_URL|__BASE64_FONT__|" input.css > placeholder.css
awk '
  BEGIN {
    while ((getline line < "font.woff2.b64") > 0) {
      base64 = base64 line
    }
    close("font.woff2.b64")
  }
  {
    gsub("__BASE64_FONT__", base64)
    print
  }
' placeholder.css > output.css

mkdir -p docs/material-symbols
mv output.css docs/material-symbols/font.css
rm -rf font.woff2 font.woff2.b64 input.css placeholder.css

echo $APACHE_LICENSE | base64 -d | gzip -d > docs/material-symbols/LICENSE
